function BUILD_PG2(q):
    points <- empty list; seen <- empty set
    for each nonzero vector v in (F_q)^3:
        i <- index of first nonzero coordinate of v
        nv <- v scaled by (v[i])^{-1} mod q   # normalize
        if nv not in seen: add nv to points and seen
    lines <- empty list
    for each normal in points:               # self-dual
        members <- { idx : <normal, points[idx]> = 0 mod q }
        append members to lines
    return (points, lines)

