function EXPECTED_COVER_TIME(n, lines):
    total <- 0
    for k from 1 to n:
        Sk <- 0
        for each k-subset A of {0,...,n-1}:
            avoid <- #{ line in lines : line disjoint from A }
            p <- avoid / |lines|
            Sk <- Sk + 1 / (1 - p)
        total <- total + (-1)^{k+1} * Sk
    return total
